INSERT INTO public.daily_sparks (quote, author, category, image_url) VALUES
('Discipline is choosing between what you want now and what you want most.', 'Abraham Lincoln', '#Consistency', 'https://images.unsplash.com/photo-1431794060787-54163dd51d62?auto=format&fit=crop&w=1200&q=80'),
('We are what we repeatedly do. Excellence, then, is not an act, but a habit.', 'Aristotle', '#Consistency', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80'),
('Small disciplines repeated with consistency every day lead to great achievements.', 'John C. Maxwell', '#Consistency', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=80'),
('Success is the sum of small efforts, repeated day in and day out.', 'Robert Collier', '#Consistency', 'https://images.unsplash.com/photo-1433086966358-54859d0ed716?auto=format&fit=crop&w=1200&q=80'),
('Long-term consistency trumps short-term intensity.', 'Bruce Lee', '#Consistency', 'https://images.unsplash.com/photo-1508739773434-c26b3d09e071?auto=format&fit=crop&w=1200&q=80'),
('Motivation gets you going, but discipline keeps you growing.', 'John C. Maxwell', '#Discipline', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1200&q=80'),
('Discipline equals freedom.', 'Jocko Willink', '#Discipline', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=80'),
('He who conquers himself is the mightiest warrior.', 'Confucius', '#Discipline', 'https://images.unsplash.com/photo-1518495973542-4542c06a5843?auto=format&fit=crop&w=1200&q=80'),
('Rule your mind or it will rule you.', 'Horace', '#Discipline', 'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1200&q=80'),
('The first and best victory is to conquer self.', 'Plato', '#Discipline', 'https://images.unsplash.com/photo-1418065460487-3e41a6c84dc5?auto=format&fit=crop&w=1200&q=80'),
('Concentrate all your thoughts upon the work at hand. The sun''s rays do not burn until brought to a focus.', 'Alexander Graham Bell', '#Focus', 'https://images.unsplash.com/photo-1497436072909-60f360e1d4b1?auto=format&fit=crop&w=1200&q=80'),
('Lack of direction, not lack of time, is the problem. We all have twenty-four hour days.', 'Zig Ziglar', '#Focus', 'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1200&q=80'),
('Simplicity is the prerequisite for reliability.', 'Edsger W. Dijkstra', '#Focus', 'https://images.unsplash.com/photo-1505765050516-f72dcac9c60e?auto=format&fit=crop&w=1200&q=80'),
('Starve your distractions, feed your focus.', 'Unknown', '#Focus', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80'),
('The successful warrior is the average man, with laser-like focus.', 'Bruce Lee', '#Focus', 'https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1200&q=80'),
('Quiet minds cannot be perplexed or frightened.', 'Robert Louis Stevenson', '#Focus', 'https://images.unsplash.com/photo-1476820865390-c52aeebb9891?auto=format&fit=crop&w=1200&q=80'),
('It does not matter how slowly you go as long as you do not stop.', 'Confucius', '#Resilience', 'https://images.unsplash.com/photo-1499002238440-d264edd596ec?auto=format&fit=crop&w=1200&q=80'),
('The impediment to action advances action. What stands in the way becomes the way.', 'Marcus Aurelius', '#Resilience', 'https://images.unsplash.com/photo-1505765050516-f72dcac9c60e?auto=format&fit=crop&w=1200&q=80'),
('Fall seven times and stand up eight.', 'Japanese Proverb', '#Resilience', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1200&q=80'),
('Tough times never last, but tough people do.', 'Robert H. Schuller', '#Resilience', 'https://images.unsplash.com/photo-1475921088768-304f80cabb91?auto=format&fit=crop&w=1200&q=80'),
('Hardships often prepare ordinary people for an extraordinary destiny.', 'C.S. Lewis', '#Resilience', 'https://images.unsplash.com/photo-1433086966358-54859d0ed716?auto=format&fit=crop&w=1200&q=80'),
('He who has a why to live can bear almost any how.', 'Friedrich Nietzsche', '#Resilience', 'https://images.unsplash.com/photo-1504567961542-e24d9439a724?auto=format&fit=crop&w=1200&q=80'),
('You have power over your mind - not outside events. Realize this, and you will find strength.', 'Marcus Aurelius', '#Mindfulness', 'https://images.unsplash.com/photo-1473448912268-2022ce9509d8?auto=format&fit=crop&w=1200&q=80'),
('Peace comes from within. Do not seek it without.', 'Buddha', '#Mindfulness', 'https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&w=1200&q=80'),
('Stillness is where creativity and solutions to problems are found.', 'Eckhart Tolle', '#Mindfulness', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=80'),
('Almost everything will work again if you unplug it for a few minutes, including you.', 'Anne Lamott', '#Mindfulness', 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1200&q=80'),
('In the midst of movement and chaos, keep stillness inside of you.', 'Deepak Chopra', '#Mindfulness', 'https://images.unsplash.com/photo-1500534314209-a25ddb2bd429?auto=format&fit=crop&w=1200&q=80'),
